!function(r){function n(n){for(var e,i,o=n[0],m=n[1],c=n[2],s=0,g=[];s<o.length;s++)i=o[s],Object.prototype.hasOwnProperty.call(t,i)&&t[i]&&g.push(t[i][0]),t[i]=0;for(e in m)Object.prototype.hasOwnProperty.call(m,e)&&(r[e]=m[e]);for(u&&u(n);g.length;)g.shift()();return p.push.apply(p,c||[]),a()}function a(){for(var r,n=0;n<p.length;n++){for(var a,i=p[n],o=!0,m=1;m<i.length;m++)a=i[m],0!==t[a]&&(o=!1);o&&(p.splice(n--,1),r=e(e.s=i[0]))}return r}function e(n){if(i[n])return i[n].exports;var a=i[n]={i:n,l:!1,exports:{}};return r[n].call(a.exports,a,a.exports,e),a.l=!0,a.exports}var i={},t={6:0},p=[];e.m=r,e.c=i,e.d=function(r,n,a){e.o(r,n)||Object.defineProperty(r,n,{enumerable:!0,get:a})},e.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},e.t=function(r,n){if(1&n&&(r=e(r)),8&n)return r;if(4&n&&"object"==typeof r&&r&&r.__esModule)return r;var a=Object.create(null);if(e.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:r}),2&n&&"string"!=typeof r)for(var i in r)e.d(a,i,function(n){return r[n]}.bind(null,i));return a},e.n=function(r){var n=r&&r.__esModule?function(){return r.default}:function(){return r};return e.d(n,"a",n),n},e.o=function(r,n){return Object.prototype.hasOwnProperty.call(r,n)},e.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=n,o=o.slice();for(var c=0;c<o.length;c++)n(o[c]);var u=m;p.push([56,0]),a()}({56:function(r,n,a){"use strict";a.r(n);var e=a(0);Object(e.a)("ru","army",a(57),a(1))},57:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"火炮","link":"ru_army#ru_army_cannon"}],"model":"ZIS-3型76mm加农炮","description":"<h6>综述：</h6><p>ZIS-3型76.2毫米加农炮是二战苏军一种极为出名的火炮，它是在ZIS-2型57mm反坦克炮的炮架上换装76mm长炮管，并加装了炮口制退器，垂直半自动锲型锁、液压驻退机和复位机等，从而成为一种新的威力更大的火炮。</p><p>ZIS-3型76毫米加农炮在1941年底正式量产，1942年大量装备苏军炮兵部队，因此又称为“1942式76mm加农炮”。由于它结构简单，制造成本低廉、易于生产，二战期间，该型炮产量高达十万门以上。</p><p>ZIS-3型76毫米加农炮可以用作反坦克，使用含钨穿甲弹可在600米距离对德军虎式坦克造成较大威胁，同时该炮也可用作火力支援和攻击坚固掩体。该型炮重量轻，便于机动，是苏军步兵师、团级必配的火炮。由于ZIS-3型76毫米加农炮射速很高，炮弹出膛后，几乎听不到飞驰过程的啸叫声，总是在听到发射时“咻”的一声之后，紧接着就听到命中目标的“碰”的一声，如果第一发没能命中，第二发、第三发随即接踵而至，因此德国士兵习惯地叫它“咻碰炮”，而这种声音也几乎成了二战时德国士兵的梦魇。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/ru/army/ru_army_cannonZIS3_10.jpg","description":"<h6>ZIS-3型（1942式）76mm加农炮</h6><p></p><p>基本技术数据：</p><p>口径：76.2毫米，倍径：42.6；</p><p>全长：6.1米，宽：1.4米，高1.3米；</p><p>战斗全重：1.15吨；</p><p>高低射界：-5-+27度（早期），-5-+37度（后期），方向射界：左27-右27度；</p><p>射速：25发/分钟（持续射击时：15发/分钟）；</p><p>炮口初速：680米/秒；</p><p>最大射程：13.29千米；</p><p>穿甲能力：穿甲弹在914米距离可击穿81毫米的30度角装甲。</p>","caption":""}],"part2title":"战场上的ZIS-3型76mm加农炮","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_cannonZIS3_20.jpg","description":"1942年冬季，东线苏联战场，苏军阵地上的一门1942式76毫米加农炮，一名弹药手正准备将炮弹推入炮膛。1942式76毫米加农炮是一种多功能火炮，除可发射高爆榴弹、榴霰弹、烟幕弹等多种炮弹作杀伤、掩护和攻坚外，也能发射反坦克穿甲弹作反坦克炮用。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_21.jpg","description":"1942年，东线苏联战场，苏军一门ZIS-3型76毫米加农炮正在向城中的德军开火。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_22.jpg","description":"1942年冬季，东线苏联战场斯大林格勒地区，在拉多加湖区的雪地中行进的1门苏军1942式76mm加农炮与炮班士兵，苏军通过这条连接被封锁的斯大林格勒的生命运输线不断往前方运送反击的人员、武器弹药与各种战场急需物资。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_23.jpg","description":"东线战场，苏军一门正在射击中的1942式76毫米加农炮。在1942年的斯大林格勒保卫战和1943年7月的库尔斯克会战中，苏军先后出动大量包括1942式76毫米加农炮在内的近两万门各型火炮与德军对抗。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_24.jpg","description":"1944年7月，东线战场波兰东部卢布林，一门布置在城区阵地中的苏军1942式76毫米加农炮，炮长正用望远镜观察目标。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_25.jpg","description":"1945年4月，东线德国战场奥得布鲁（Oderbruch）地区，苏军一个师属炮兵营的1942式（ZIS-3型）76毫米加农炮阵地，阵地上密集地一字排开多门76毫米加农炮。在苏军中，一个普通步兵师的ZIS-3炮标准装备是32门，近卫步兵师则为36门。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_26.jpg","description":"1945年3月，东线德国战场但泽市城区，苏军一门1942式76毫米加农炮正在向德军阵地开火。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_27.jpg","description":"1945年春季，东线德国战场，一门投入战斗的苏军1942式76mm加农炮。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_28.jpg","description":"1942年间，东线苏联战场，苏军一支炮兵部队正在转移，多门1942式76mm加农炮用马匹拖带着在公路行进，为了避免被德国飞机发现，这些炮都用树枝作了伪装。1942式76mm加农炮可用拖拉机，吉普车，坦克甚至马匹拖拽，它1.15吨的重量能让它轻易地在苏联各种不同路况的道路上行动，即便陷入雪地泥泞中，也可以通过人力来推动。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_29.jpg","description":"东线苏联战场，苏军两辆T-70坦克牵引着1942式76mm加农炮在雪地中行进。二战中期，T-70这种轻坦克已无法上战场作战了，正好作76mm火炮牵引车用。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_30.jpg","description":"1944年东线苏联战场，苏军一炮兵团的1942式76mm加农炮在卡车牵引下正向前线开进。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_31.jpg","description":"1944年东线苏联战场，隶属苏联白俄罗斯方面军的多名炮兵正努力将一门1942式76mm加农炮推出土坑，准备重新牵挂在路上的牵引卡车后面。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_32.jpg","description":"绘画：东线战场，在城市废墟中英勇作战的一门苏军1942式76mm加农炮及其炮班成员。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_33.jpg","description":"绘画：东线战场，苏军1942式76mm加农炮阵地。","caption":""},{"image":"imgs/ru/army/ru_army_cannonZIS3_34.jpg","description":"绘画：苏军1942式76mm加农炮。","caption":""}]}')}});